package ama.storage;
import ama.transcript.JdbcMinutesFactsReader;import ama.contract.MinutesContracts.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class Task09GenerationRichIT extends Task09GenerationExternalIT {
 @Override String instruction(){return "controlled:rich-output";}
 @Override void afterCandidate(Map<String,Object> candidate,JdbcMinutesFactsReader.Snapshot facts)throws Exception {
  var rows=facts.facts().rows();var elements=rows.stream().filter(r->r.table()==Table.MINUTES_ELEMENT).toList();assertEquals(8,elements.size());assertEquals(Set.of(Category.values()).size(),elements.stream().map(r->r.string("category")).distinct().count());assertTrue(elements.stream().allMatch(r->r.string("support_state").equals("PARTIAL")));var accepted=rows.stream().filter(r->r.table()==Table.ACTION_ITEM).toList();assertEquals(2,accepted.size());assertTrue(accepted.stream().allMatch(r->r.nullableString("owner_enterprise_id")==null&&r.nullableString("owner_display")==null&&r.nullableString("due_on")==null));var suggestions=rows.stream().filter(r->r.table()==Table.ACTION_SUGGESTION).toList();assertEquals(2,suggestions.size());assertEquals(1,suggestions.stream().filter(r->r.nullableString("owner_mention")==null).count());assertEquals(1,suggestions.stream().filter(r->r.nullableString("due_on")==null).count());assertEquals(9,rows.stream().filter(r->r.table()==Table.EVIDENCE_LINK).count());assertEquals(9,facts.facts().evidenceAnchors().size());assertEquals(2,rows.stream().filter(r->r.table()==Table.SENSITIVE_DETECTION).count());assertEquals(2,rows.stream().filter(r->r.table()==Table.SENSITIVE_DETECTION_SOURCE).count());assertEquals(1,rows.stream().filter(r->r.table()==Table.BACKGROUND_NOTE).count());assertEquals(1,rows.stream().filter(r->r.table()==Table.BACKGROUND_NOTE_SOURCE).count());assertEquals(1,rows.stream().filter(r->r.table()==Table.SOURCE_LOCATOR).count());assertTrue(rows.stream().noneMatch(r->r.table()==Table.RESULT_REVIEW));
 }
}
